import{_ as a,o,c as s,a4 as c}from"./chunks/framework.DPU9SBEx.js";const m=JSON.parse('{"title":"Full-TypeScript Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),t={name:"guide/architecture.md"};function n(r,e,i,p,d,l){return o(),s("div",null,[...e[0]||(e[0]=[c('<h1 id="full-typescript-architecture" tabindex="-1">Full-TypeScript Architecture <a class="header-anchor" href="#full-typescript-architecture" aria-label="Permalink to &quot;Full-TypeScript Architecture&quot;">​</a></h1><p>Komerce Design (<code>apps/api</code> — <code>@komerce-design/api</code>) is a 100% TypeScript / Node.js 22 CLI and service structured around clean domain and application boundaries with zero database or subprocess serialization overhead.</p><h2 id="module-boundaries" tabindex="-1">Module Boundaries <a class="header-anchor" href="#module-boundaries" aria-label="Permalink to &quot;Module Boundaries&quot;">​</a></h2><p>Dependencies flow inward toward the domain and application layer:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Local CLI / Inbound HTTP ]       [ Core Application (`src/app/`) ]      [ In-Process Packages &amp; Workspace ]</span></span>\n<span class="line"><span>  CLI (`cli.ts`, `local-runner.ts`) -&gt; Service (`service.ts`)            ----&gt; @komerce-design/mitosis-author</span></span>\n<span class="line"><span>  - `komerce sync [file.json]`         JobRunner &amp; AuthorRunner               - Deterministic Blueprint (`blueprint.ts`)</span></span>\n<span class="line"><span>  - `komerce regen &lt;Comp&gt; &lt;notes&gt;`     Local Regen (`regenerate.ts`)          - Agy CLI &amp; OpenAI Agent</span></span>\n<span class="line"><span>  - `komerce listen` (127.0.0.1)       Incremental Diff (`sync.ts`)</span></span>\n<span class="line"><span>  HTTP Router (`src/http/`)            AST Docgen (`docgen-ast.ts`)     ----&gt; @komerce-design/mitosis-compiler</span></span>\n<span class="line"><span>  - /v1/extractions, /v1/syncs/*       Token Resolver (`tokens.ts`)           - AST Normalizer &amp; Typecheck Gate</span></span>\n<span class="line"><span>  - /v1/jobs/{id}/events (SSE)                                                - 5-Target Framework Adapters</span></span>\n<span class="line"><span>                                                                        ----&gt; Store (`src/store/`)</span></span>\n<span class="line"><span>                                                                              - In-Memory Store (`mem-store.ts`) + Disk (`src/*`)</span></span>\n<span class="line"><span>                                                                        ----&gt; Publishers (`src/publisher/`)</span></span>\n<span class="line"><span>                                                                              - LocalWorkspacePublisher (`src/*` &amp; `library/*`)</span></span>\n<span class="line"><span>                                                                              - Download ZIP &amp; Optional GitHub PR Publisher</span></span></code></pre></div><h3 id="workspace-source-output-layout" tabindex="-1">Workspace Source &amp; Output Layout <a class="header-anchor" href="#workspace-source-output-layout" aria-label="Permalink to &quot;Workspace Source &amp; Output Layout&quot;">​</a></h3><ul><li><code>src/{components,icons,tokens,examples}</code>: Single source of truth for universal <code>.lite.tsx</code> components, headless <code>core-*.ts</code> / <code>utils.ts</code>, and semantic design tokens.</li><li><code>library/{tokens,react,vue3,svelte,vue2,angular}</code>: Standalone npm workspace packages (<code>@komerce-design/*</code>) compiled from <code>src/*</code> by <code>scripts/compile-library.mjs</code>.</li></ul><h3 id="domain-layer-apps-api-src-domain" tabindex="-1">Domain Layer (<code>apps/api/src/domain/</code>) <a class="header-anchor" href="#domain-layer-apps-api-src-domain" aria-label="Permalink to &quot;Domain Layer (`apps/api/src/domain/`)&quot;">​</a></h3><ul><li><code>models.ts</code>: Pure entity types (<code>Job</code>, <code>FigmaComponentSpec</code>, <code>CompiledArtifact</code>, <code>SyncPlan</code>, <code>PublisherType</code>) and component name normalization (<code>normalizeComponentName</code>, <code>camelToKebab</code>).</li><li><code>artifact-path.ts</code>: Single source of truth mapping artifacts (<code>mitosis</code>, <code>tokens</code>, <code>docs</code>) to repository paths (<code>src/components</code>, <code>src/icons</code>, <code>src/examples</code>, <code>src/tokens</code>, <code>docs/components</code>, <code>docs/tokens.md</code>).</li></ul><h3 id="application-layer-apps-api-src-app" tabindex="-1">Application Layer (<code>apps/api/src/app/</code>) <a class="header-anchor" href="#application-layer-apps-api-src-app" aria-label="Permalink to &quot;Application Layer (`apps/api/src/app/`)&quot;">​</a></h3><ul><li><code>service.ts</code> &amp; <code>job-runner.ts</code>: Orchestrates extraction jobs, incremental sync plans (<code>calculateSyncPlan</code>), concurrent component authoring, and publisher invocation.</li><li><code>regenerate.ts</code>: In-process single-component regeneration (<code>regenerateComponentLocal</code>) reading local <code>src/</code> sources and <code>var/extractions/latest.json</code>, writing updated <code>.lite.tsx</code> and docs directly to disk, and recompiling <code>library/*</code>.</li><li><code>author-runner.ts</code>: Stateful cross-attempt repair loop passing <code>repairErrors</code> and <code>partialComponents</code> into <code>@komerce-design/mitosis-author</code> and verifying output via <code>@komerce-design/mitosis-compiler</code>.</li><li><code>tokens.ts</code> &amp; <code>docgen.ts</code> / <code>docgen-ast.ts</code>: Generates Tailwind v4 <code>@theme</code> (<code>theme.css</code>), CSS custom properties (<code>tokens.css</code>), and AST-driven Markdown documentation.</li></ul><h3 id="storage-publishers-apps-api-src-store-publisher" tabindex="-1">Storage &amp; Publishers (<code>apps/api/src/{store,publisher}/</code>) <a class="header-anchor" href="#storage-publishers-apps-api-src-store-publisher" aria-label="Permalink to &quot;Storage &amp; Publishers (`apps/api/src/{store,publisher}/`)&quot;">​</a></h3><ul><li><code>mem-store.ts</code>: Lightweight in-memory job and artifact store paired with direct filesystem inspection of <code>src/*</code> and <code>var/extractions/latest.json</code> (zero SQLite database required).</li><li><code>local-publisher.ts</code>: Writes universal <code>.lite.tsx</code> sources, tokens, and docs directly to the local working tree and invokes <code>scripts/compile-library.mjs</code>.</li><li><code>download-publisher.ts</code> &amp; <code>github-publisher.ts</code>: Optional ZIP bundle and remote GitHub Pull Request publishers.</li></ul>',13)])])}const h=a(t,[["render",n]]);export{m as __pageData,h as default};
